    [
        'name' => 'Single-Arm Kettlebell Swing',
        'name_ar' => 'أرجحة الكيتل بيل بيد واحدة',
        'muscle_group' => 'full_body',
        'difficulty' => 'intermediate',
        'equipment' => 'Kettlebell',
        'equipment_ar' => 'كيتل بيل',
        'description' => 'A dynamic hip-hinge exercise that targets the hamstrings, with the glutes, lower back, shoulders and calves assisting.',
        'description_ar' => 'تمرين انثناء ديناميكي من الورك يستهدف العضلات الخلفية للفخذ، مع مشاركة عضلات الأرداف وأسفل الظهر والأكتاف وعضلات السمانة.',
        'instructions' => "Stand with feet slightly wider than shoulder-width and a kettlebell on the floor a little in front of you.\nHinge at your hips with a flat back, grip the handle with one hand, and hike the kettlebell back between your legs.\nDrive your hips forward powerfully to stand tall, letting the kettlebell swing up to about chest height with a straight arm.\nExhale sharply at the top, keeping your core braced and shoulders square.\nLet the kettlebell fall back between your legs as you hinge again, then repeat and switch arms after the set.",
        'instructions_ar' => "قف مع جعل قدميك أعرض قليلاً من عرض الكتفين، وضع الكيتل بيل على الأرض أمامك بقليل.\nانحنِ من وركيك مع ظهر مستقيم، وامسك المقبض بيد واحدة، وأرجح الكيتل بيل إلى الخلف بين ساقيك.\nادفع وركيك إلى الأمام بقوة لتقف منتصباً، تاركاً الكيتل بيل يتأرجح إلى مستوى الصدر تقريباً بذراع ممدودة.\nازفر بقوة في الأعلى، مع شدّ عضلات جذعك وإبقاء كتفيك متوازيين.\nدع الكيتل بيل يعود بين ساقيك وأنت تنحني من الوركين مجدداً، ثم كرر وبدّل الذراع بعد انتهاء المجموعة.",
        'tips' => "The power comes from your hips, not from lifting with your arm.\nDo not let your torso twist toward the kettlebell.",
        'tips_ar' => "تأتي القوة من وركيك لا من الرفع بذراعك.\nلا تدع جذعك يلتف نحو الكيتل بيل.",
    ],
    [
        'name' => 'Barbell Clean and Press',
        'name_ar' => 'كلين وضغط بالبار',
        'muscle_group' => 'full_body',
